-- WASSCE Physics 2023 Questions (50 questions)

INSERT OR IGNORE INTO past_papers (id, exam_type_id, subject_id, paper_type_id, year, month, total_questions, total_marks, time_allowed, is_complete)
VALUES ('pp_wassce_phy_2023_1', 'exam_wassce', 'subj_wassce_physics', 'paper_wassce_1', 2023, 'May-June', 50, 50, 60, 1);

INSERT OR REPLACE INTO questions (id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, marks, question_number) VALUES
-- Mechanics (1-15)
('q_phy_2023_001', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The SI unit of force is:', 'multiple_choice', '["A. Joule", "B. Newton", "C. Watt", "D. Pascal"]', 'B', 'The Newton (N) is the SI unit of force, defined as kg⋅m/s².', 'easy', 1, 1),
('q_phy_2023_002', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Acceleration is defined as the rate of change of:', 'multiple_choice', '["A. Distance", "B. Displacement", "C. Speed", "D. Velocity"]', 'D', 'Acceleration is the rate of change of velocity with respect to time (a = Δv/Δt).', 'easy', 1, 2),
('q_phy_2023_003', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'A body moving with uniform velocity has:', 'multiple_choice', '["A. Zero acceleration", "B. Constant acceleration", "C. Increasing acceleration", "D. Decreasing acceleration"]', 'A', 'Uniform velocity means no change in velocity, therefore acceleration is zero.', 'easy', 1, 3),
('q_phy_2023_004', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Newton''s first law of motion is also known as the law of:', 'multiple_choice', '["A. Acceleration", "B. Action and reaction", "C. Inertia", "D. Momentum"]', 'C', 'Newton''s first law (law of inertia) states that a body remains at rest or in uniform motion unless acted upon by a force.', 'easy', 1, 4),
('q_phy_2023_005', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The momentum of a 5 kg object moving at 4 m/s is:', 'multiple_choice', '["A. 1.25 kg⋅m/s", "B. 9 kg⋅m/s", "C. 20 kg⋅m/s", "D. 0.8 kg⋅m/s"]', 'C', 'Momentum = mass × velocity = 5 kg × 4 m/s = 20 kg⋅m/s.', 'easy', 1, 5),
('q_phy_2023_006', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Work is done when:', 'multiple_choice', '["A. Force is applied", "B. Force causes displacement", "C. Object is stationary", "D. Force is perpendicular to motion"]', 'B', 'Work is done when a force causes an object to move in the direction of the force (W = F × d).', 'easy', 1, 6),
('q_phy_2023_007', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The kinetic energy of a body is given by:', 'multiple_choice', '["A. mgh", "B. ½mv²", "C. mv", "D. Fd"]', 'B', 'Kinetic energy KE = ½mv², where m is mass and v is velocity.', 'easy', 1, 7),
('q_phy_2023_008', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'A machine has a velocity ratio of 5 and efficiency of 80%. Its mechanical advantage is:', 'multiple_choice', '["A. 4", "B. 5", "C. 6.25", "D. 0.16"]', 'A', 'Efficiency = (MA/VR) × 100%. So MA = Efficiency × VR / 100 = 80 × 5 / 100 = 4.', 'medium', 1, 8),
('q_phy_2023_009', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The acceleration due to gravity at the Earth''s surface is approximately:', 'multiple_choice', '["A. 9.8 m/s", "B. 9.8 m/s²", "C. 10 m/s", "D. 10 kg"]', 'B', 'The acceleration due to gravity g ≈ 9.8 m/s² (or approximately 10 m/s² for calculations).', 'easy', 1, 9),
('q_phy_2023_010', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'An object is thrown vertically upward. At maximum height, its:', 'multiple_choice', '["A. Velocity is maximum", "B. Velocity is zero", "C. Acceleration is zero", "D. Kinetic energy is maximum"]', 'B', 'At maximum height, the velocity momentarily becomes zero before the object starts falling.', 'easy', 1, 10),
('q_phy_2023_011', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The principle of moments states that for a body in equilibrium:', 'multiple_choice', '["A. All forces are equal", "B. Sum of clockwise moments equals sum of anticlockwise moments", "C. There are no forces", "D. All moments are zero"]', 'B', 'The principle of moments: Σ clockwise moments = Σ anticlockwise moments about any point.', 'medium', 1, 11),
('q_phy_2023_012', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The center of gravity of a uniform rod is at its:', 'multiple_choice', '["A. End", "B. Midpoint", "C. Quarter point", "D. Edge"]', 'B', 'For a uniform rod, the center of gravity is at the geometric center (midpoint).', 'easy', 1, 12),
('q_phy_2023_013', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Power is the rate of doing:', 'multiple_choice', '["A. Force", "B. Work", "C. Energy", "D. Momentum"]', 'B', 'Power is the rate of doing work or transferring energy (P = W/t).', 'easy', 1, 13),
('q_phy_2023_014', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'A body of mass 2 kg falls from a height of 10 m. Its potential energy at the top is (g=10 m/s²):', 'multiple_choice', '["A. 20 J", "B. 100 J", "C. 200 J", "D. 50 J"]', 'C', 'PE = mgh = 2 × 10 × 10 = 200 J.', 'easy', 1, 14),
('q_phy_2023_015', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Friction can be reduced by:', 'multiple_choice', '["A. Increasing surface roughness", "B. Lubrication", "C. Increasing normal force", "D. Increasing contact area"]', 'B', 'Lubrication (oil, grease) reduces friction by creating a layer between surfaces.', 'easy', 1, 15),

-- Waves and Optics (16-25)
('q_phy_2023_016', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The speed of a wave is given by:', 'multiple_choice', '["A. v = f/λ", "B. v = fλ", "C. v = λ/f", "D. v = f + λ"]', 'B', 'Wave speed = frequency × wavelength (v = fλ).', 'easy', 1, 16),
('q_phy_2023_017', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Sound waves are:', 'multiple_choice', '["A. Transverse waves", "B. Longitudinal waves", "C. Electromagnetic waves", "D. Standing waves"]', 'B', 'Sound waves are longitudinal waves where particles vibrate parallel to the direction of wave travel.', 'easy', 1, 17),
('q_phy_2023_018', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The phenomenon of light bending when passing from one medium to another is called:', 'multiple_choice', '["A. Reflection", "B. Refraction", "C. Diffraction", "D. Interference"]', 'B', 'Refraction is the bending of light as it passes from one medium to another due to change in speed.', 'easy', 1, 18),
('q_phy_2023_019', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The critical angle exists when light travels from:', 'multiple_choice', '["A. Less dense to denser medium", "B. Denser to less dense medium", "C. Same density media", "D. Vacuum only"]', 'B', 'Critical angle occurs when light travels from a denser medium to a less dense medium.', 'medium', 1, 19),
('q_phy_2023_020', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'A convex lens is also known as a:', 'multiple_choice', '["A. Diverging lens", "B. Converging lens", "C. Plane lens", "D. Concave lens"]', 'B', 'A convex (converging) lens is thicker in the middle and brings parallel rays to a focus.', 'easy', 1, 20),
('q_phy_2023_021', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The image formed by a plane mirror is:', 'multiple_choice', '["A. Real and inverted", "B. Virtual and upright", "C. Real and upright", "D. Virtual and inverted"]', 'B', 'A plane mirror produces a virtual, upright, laterally inverted image of the same size.', 'easy', 1, 21),
('q_phy_2023_022', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The phenomenon responsible for the formation of rainbows is:', 'multiple_choice', '["A. Reflection only", "B. Refraction only", "C. Dispersion", "D. Diffraction"]', 'C', 'Rainbows form due to dispersion - the separation of white light into its component colors.', 'easy', 1, 22),
('q_phy_2023_023', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The frequency of a wave with period 0.02 s is:', 'multiple_choice', '["A. 0.02 Hz", "B. 20 Hz", "C. 50 Hz", "D. 500 Hz"]', 'C', 'Frequency = 1/Period = 1/0.02 = 50 Hz.', 'easy', 1, 23),
('q_phy_2023_024', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Echo is produced due to:', 'multiple_choice', '["A. Refraction of sound", "B. Reflection of sound", "C. Diffraction of sound", "D. Interference of sound"]', 'B', 'Echo is produced when sound waves reflect off a surface and return to the listener.', 'easy', 1, 24),
('q_phy_2023_025', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The power of a lens is measured in:', 'multiple_choice', '["A. Meters", "B. Diopters", "C. Joules", "D. Watts"]', 'B', 'Lens power is measured in diopters (D), where P = 1/f (f in meters).', 'easy', 1, 25),

-- Electricity and Magnetism (26-40)
('q_phy_2023_026', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Electric current is the flow of:', 'multiple_choice', '["A. Protons", "B. Neutrons", "C. Electrons", "D. Atoms"]', 'C', 'Electric current is the flow of electrons (negative charges) through a conductor.', 'easy', 1, 26),
('q_phy_2023_027', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The SI unit of electrical resistance is:', 'multiple_choice', '["A. Ampere", "B. Volt", "C. Ohm", "D. Watt"]', 'C', 'The Ohm (Ω) is the SI unit of electrical resistance.', 'easy', 1, 27),
('q_phy_2023_028', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'According to Ohm''s law, V = IR. If V = 12 V and I = 3 A, then R =:', 'multiple_choice', '["A. 36 Ω", "B. 15 Ω", "C. 4 Ω", "D. 9 Ω"]', 'C', 'R = V/I = 12/3 = 4 Ω.', 'easy', 1, 28),
('q_phy_2023_029', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'When resistors are connected in series, the total resistance:', 'multiple_choice', '["A. Decreases", "B. Increases", "C. Remains the same", "D. Becomes zero"]', 'B', 'In series: R_total = R1 + R2 + R3 + ... The total resistance increases.', 'easy', 1, 29),
('q_phy_2023_030', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Electrical power is calculated as:', 'multiple_choice', '["A. P = V/I", "B. P = I/V", "C. P = VI", "D. P = V + I"]', 'C', 'Electrical power P = VI (also P = I²R or P = V²/R).', 'easy', 1, 30),
('q_phy_2023_031', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'A fuse is used to:', 'multiple_choice', '["A. Increase current", "B. Decrease voltage", "C. Protect circuits from excessive current", "D. Store charge"]', 'C', 'A fuse melts and breaks the circuit when current exceeds a safe level, protecting the circuit.', 'easy', 1, 31),
('q_phy_2023_032', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The device that converts mechanical energy to electrical energy is:', 'multiple_choice', '["A. Motor", "B. Generator", "C. Transformer", "D. Capacitor"]', 'B', 'A generator converts mechanical energy to electrical energy through electromagnetic induction.', 'easy', 1, 32),
('q_phy_2023_033', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'A transformer works on the principle of:', 'multiple_choice', '["A. Electrolysis", "B. Electromagnetic induction", "C. Electrostatics", "D. Thermoelectricity"]', 'B', 'Transformers use electromagnetic induction to change voltage levels in AC circuits.', 'easy', 1, 33),
('q_phy_2023_034', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Like magnetic poles:', 'multiple_choice', '["A. Attract each other", "B. Repel each other", "C. Have no effect", "D. Cancel out"]', 'B', 'Like poles (N-N or S-S) repel; unlike poles (N-S) attract.', 'easy', 1, 34),
('q_phy_2023_035', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The unit of capacitance is:', 'multiple_choice', '["A. Coulomb", "B. Farad", "C. Henry", "D. Tesla"]', 'B', 'Capacitance is measured in Farads (F). C = Q/V.', 'easy', 1, 35),
('q_phy_2023_036', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'An ammeter is connected in:', 'multiple_choice', '["A. Series", "B. Parallel", "C. Either series or parallel", "D. Neither"]', 'A', 'An ammeter is connected in series to measure the current flowing through the circuit.', 'easy', 1, 36),
('q_phy_2023_037', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The energy stored in a capacitor is:', 'multiple_choice', '["A. ½CV²", "B. CV", "C. C/V", "D. 2CV²"]', 'A', 'Energy stored in a capacitor E = ½CV² = ½QV = Q²/2C.', 'medium', 1, 37),
('q_phy_2023_038', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Fleming''s right-hand rule is used for:', 'multiple_choice', '["A. Motors", "B. Generators", "C. Transformers", "D. Capacitors"]', 'B', 'Fleming''s right-hand rule determines the direction of induced current in generators.', 'medium', 1, 38),
('q_phy_2023_039', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The domestic electricity supply in Ghana is:', 'multiple_choice', '["A. DC at 220V", "B. AC at 230V", "C. DC at 110V", "D. AC at 110V"]', 'B', 'Ghana uses AC (alternating current) at approximately 230V, 50Hz.', 'easy', 1, 39),
('q_phy_2023_040', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'A step-up transformer:', 'multiple_choice', '["A. Decreases voltage", "B. Increases voltage", "C. Changes DC to AC", "D. Changes AC to DC"]', 'B', 'A step-up transformer increases voltage (has more turns on the secondary coil).', 'easy', 1, 40),

-- Heat and Modern Physics (41-50)
('q_phy_2023_041', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Heat is transferred through vacuum by:', 'multiple_choice', '["A. Conduction", "B. Convection", "C. Radiation", "D. All methods"]', 'C', 'Only radiation can transfer heat through a vacuum, as it doesn''t require a medium.', 'easy', 1, 41),
('q_phy_2023_042', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The SI unit of temperature is:', 'multiple_choice', '["A. Celsius", "B. Fahrenheit", "C. Kelvin", "D. Joule"]', 'C', 'Kelvin (K) is the SI unit of temperature. 0 K = -273.15°C.', 'easy', 1, 42),
('q_phy_2023_043', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Specific heat capacity is the heat required to raise the temperature of:', 'multiple_choice', '["A. Any mass by 1°C", "B. 1 kg by any temperature", "C. 1 kg by 1°C", "D. 1 g by 100°C"]', 'C', 'Specific heat capacity is the heat needed to raise 1 kg of a substance by 1°C (or 1 K).', 'easy', 1, 43),
('q_phy_2023_044', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'During change of state, temperature:', 'multiple_choice', '["A. Increases", "B. Decreases", "C. Remains constant", "D. Fluctuates"]', 'C', 'During phase change, temperature remains constant as energy is used to change the state.', 'easy', 1, 44),
('q_phy_2023_045', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Latent heat of vaporization is the heat required to:', 'multiple_choice', '["A. Melt a solid", "B. Change liquid to gas at constant temperature", "C. Heat a gas", "D. Cool a liquid"]', 'B', 'Latent heat of vaporization is needed to change liquid to gas without temperature change.', 'easy', 1, 45),
('q_phy_2023_046', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Radioactive decay is:', 'multiple_choice', '["A. Predictable for individual atoms", "B. A random process", "C. Only alpha decay", "D. Caused by temperature"]', 'B', 'Radioactive decay is a random, spontaneous process that cannot be predicted for individual atoms.', 'medium', 1, 46),
('q_phy_2023_047', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Half-life is the time for:', 'multiple_choice', '["A. All atoms to decay", "B. Half the atoms to decay", "C. Activity to become zero", "D. Mass to double"]', 'B', 'Half-life is the time taken for half of the radioactive atoms to decay.', 'easy', 1, 47),
('q_phy_2023_048', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Alpha particles are:', 'multiple_choice', '["A. Electrons", "B. Protons", "C. Helium nuclei", "D. Neutrons"]', 'C', 'Alpha particles are helium nuclei (2 protons + 2 neutrons).', 'easy', 1, 48),
('q_phy_2023_049', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'The photoelectric effect supports the:', 'multiple_choice', '["A. Wave nature of light", "B. Particle nature of light", "C. Dual nature of matter", "D. Continuous spectrum"]', 'B', 'The photoelectric effect demonstrates that light behaves as particles (photons) with quantized energy.', 'medium', 1, 49),
('q_phy_2023_050', 'subj_wassce_physics', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_phy_2023_1', 'Nuclear fission involves:', 'multiple_choice', '["A. Joining small nuclei", "B. Splitting large nuclei", "C. Electron emission", "D. Neutron capture only"]', 'B', 'Nuclear fission is the splitting of a large nucleus into smaller fragments, releasing energy.', 'easy', 1, 50);
